import operator
from typing import List, Tuple, Union, Dict, Callable, Any, Optional
from functools import wraps

def validate_numeric(func: Callable[..., Any]) -> Callable[..., Any]:
    """Decorator to ensure all positional and keyword inputs are numeric."""
    @wraps(func)
    def wrapper(*args: Any, **kwargs: Any) -> Any:
        # Check positional arguments excluding 'self'
        for arg in args[1:]:
            if not isinstance(arg, (int, float)):
                raise TypeError(f"All calculator positional inputs must be numeric. Received: {type(arg).__name__}")
        # Check keyword arguments
        for val in kwargs.values():
            if not isinstance(val, (int, float)):
                raise TypeError(f"All calculator keyword inputs must be numeric. Received: {type(val).__name__}")
        return func(*args, **kwargs)
    return wrapper

