        """Stores a value into the calculator memory and records the operation."""
        self._memory = float(value)
        self._record("memory_store", float(value), 0.0, float(value))

    def memory_recall(self) -> Optional[float]:
        """Returns the current value stored in memory."""
        return self._memory

    def memory_clear(self) -> None:
        """Resets the memory to None and records the operation."""
        self._memory = None
        self._record("memory_clear", 0.0, 0.0, 0.0)

