    def _mul_logic(self, a: float, b: float) -> float:
        return float(a * b)

    def _div_logic(self, a: float, b: float) -> float:
        if b == 0:
            raise ValueError("Cannot divide by zero.")
        return float(a / b)

    def _pow_logic(self, a: float, b: float) -> float:
        try:
            res = float(a ** b)
            if isinstance(res, complex):
                raise ValueError("Power operation resulted in a complex number.")
            return res
        except (ValueError, ZeroDivisionError, OverflowError, TypeError) as e:
            raise ValueError(f"Power operation failed: {e}")

    def _mod_logic(self, a: float, b: float) -> float:
        if b == 0:
            raise ValueError("Cannot modulo by zero.")
        return float(a % b)

