        elif isinstance(node, ast.BinOp):
            left = self._eval_node(node.left, depth + 1)
            right = self._eval_node(node.right, depth + 1)
            mapping = {
                ast.Add: self._add_logic,
                ast.Sub: self._sub_logic,
                ast.Mult: self._mul_logic,
                ast.Div: self._div_logic,
                ast.Pow: self._pow_logic,
