    assert calc.subtract(10, 5) == 5
    assert calc.subtract(5, 10) == -5

def test_multiply(calc):
    assert calc.multiply(3, 4) == 12
    assert calc.multiply(-2, 5) == -10

def test_divide(calc):
    assert calc.divide(10, 2) == 5
    assert calc.divide(9, 3) == 3

def test_divide_by_zero(calc):
    with pytest.raises(ValueError, match="Division by zero"):
        calc.divide(10, 0)

def test_get_history_is_copy(calc):
    calc.add(1, 2)
    history = calc.get_history()
    history.clear()
    assert len(calc.get_history()) == 1

def test_clear_history(calc):
    calc.add(1, 1)
    calc.subtract(5, 2)
    calc.clear_history()
    assert len(calc.get_history()) == 0

def test_history_tracking(calc):
    calc.add(1, 2)
    calc.multiply(3, 4)
    history = calc.get_history()
    assert len(history) == 2
    assert history[0] == ("add", 1.0, 2.0, 3.0)
    assert history[1] == ("multiply", 3.0, 4.0, 12.0)

def test_evaluate_basic(calc):
    assert calc.evaluate("2 + 3 * 4") == 14.0
    assert calc.evaluate("(10 - 2) / 2") == 4.0
    assert len(calc.get_history()) >= 1

def test_evaluate_pow(calc):
    assert calc.evaluate("2 ** 3") == 8.0

